-- Reference site shows a small note under the login button explaining the
-- PIN is admin-set and changeable afterward -- we had no equivalent text.
insert into translation (key, value_ar, value_en, value_hi) values
    ('login.pinHint', 'رمز الدخول يحدده مدير النظام عند إنشاء حسابك، ويمكنك تغييره بنفسك بعد الدخول من القائمة العلوية.', 'Your PIN is set by the system admin when your account is created, and you can change it yourself after logging in from the top menu.', 'आपका पिन खाता बनाते समय सिस्टम व्यवस्थापक द्वारा सेट किया जाता है, और आप लॉग इन करने के बाद इसे शीर्ष मेनू से स्वयं बदल सकते हैं।');
